  /* ======================= draft-day reveal for James Stegall ======================= */
  const HELMET = ["....XXXXXX....", "..XXXXXXXXXX..", ".XXXXXSSXXXXX.", "XXXXXXSSXXXXXX", "XXXXXXSSXXXXXX", "XXXXXXXXXXGGGG", "XXXXXXXXXXG..G", "XXXXXXXXXXGGGG", ".XXXXXXXXXG..G", "..XXXXXX...GGG"];
